arra Ranges Council acknowledges the Wurundjeri and other Kulin Nation peoples as the Traditional Owners and Custodians of these lands and waterways. We pay our respects to all Elders past, present, and emerging, who have been, and always will be, integral to the story of our region. We proudly share custodianship to care for Country together.</span></p><img src="https://www.yarraranges.vic.gov.au/files/sharedassets/public/v/3/aboriginal-torres-strait-islander-australian-flags.png?w=250&amp;h=50" alt="Aboriginal and Torres Strait Islander flags" class="acknowledgement-image fr-dib fr-fil" style="width: 199px;"></div></div><br><!-- Bottom site menu --><div class="site-footer__menu"><div class="site-footer__menu-inner"><ul><li><a href="https://www.yarraranges.vic.gov.au/Site-Footer/Sub-Footer-Links/Privacy">Privacy Statement</a></li><li><a href="https://www.yarraranges.vic.gov.au/Site-Footer/Sub-Footer-Links/Copyright-disclaimer">Copyright disclaimer</a></li><li><a href="https://www.yarraranges.vic.gov.au/Site-Footer/Sub-Footer-Links/Accessibility-statement">Accessibility</a></li></ul></div></div></footer>","WebPublishingCss":"<style>
	:root {
		/* Brand colours */
		--green: #4e7235; --green-hover: #3E5B2A; --purple: #4b477f; --white: #ffffff; --black: #000000;
		/* Layout */
		--container-max: 1200px; --content-pad-x: 24px;
		/* Header lockup */
		--logo-height: 75px; --gap-logo-text: 28px; --gap-title-subtitle: 6px;
	}

	body {
		color: var(--black); background: #fff;
	}
	/* Green banner */

	.site-header {
		background: var(--green); color: var(--white); width: 100vw; max-width: 100vw; margin-left: calc(50% - 50vw); margin-right: calc(50% - 50vw); padding: 0; overflow: visible;
	}

	.site-header__inner {
		max-width: var(--container-max); margin: 0 auto; width: 100%; padding: 20px 24px; display: flex; align-items: center; justify-content: space-between;
	}
	/* Logo */

	.brand {
		display: inline-flex; align-items: center;
	}

	.brand__logo {
		display: inline-flex; align-items: center;
	}

	.brand__logo img {
		height: var(--logo-height); width: auto; display: block;
	}
	/* Button Styles */

	button,
	input[type="button"],
	input[type="submit"],
	a.button,
	.btn,
	a.fr-green {
		background-color: var(--purple); color: #ffffff; border: none; text-decoration: none;
	}

	button:hover,
	input[type="button"]:hover,
	input[type="submit"]:hover,
	a.button:hover,
	.btn:hover,
	a.fr-green:hover {
		background-color: #3f3b6b; color: #ffffff;
	}
	/* Tab Buttons */

	.nav-tabs .nav-link {
		color: var(--purple); background-color: #f5f5f5; border: 1px solid var(--purple); border-bottom: none; padding: 0.5rem 1rem; border-radius: 0.25rem 0.25rem 0 0; transition: background-color 0.2s, color 0.2s;
	}

	.nav-tabs .nav-link.active {
		color: #ffffff; background-color: var(--purple); border-color: var(--purple);
	}

	.nav-tabs .nav-link:not(.active):hover {
		color: #000000; background-color: #dcd6f0;
	}
	/* After banner content */

	.after-banner {
		width: 100%; background: #fff;
	}

	.after-banner__inner {
		max-width: var(--container-max); margin: 0 auto; padding: 90px var(--content-pad-x) 40px var(--content-pad-x);
	}

	.site-footer {
		background-color: #4e7235; color: #ffffff; padding: 60px 24px 40px 24px; font-family: Arial, sans-serif; margin-top: 160px;
	}

	.site-footer {
		width: 100vw; max-width: 100vw; margin-left: calc(50% - 50vw); margin-right: calc(50% - 50vw);
	}

	.site-footer h1,
	.site-footer h2,
	.site-footer h3,
	.site-footer h4 {
		font-family: inherit !important;
	}

	.site-footer__columns {
		max-width: var(--container-max); margin: 0 auto; display: flex; justify-content: space-between; flex-wrap: wrap; gap: 30px; margin-bottom: 30px;
	}

	.footer-column {
		flex: 1 1 250px; min-width: 200px;
	}
	/* Footer headings */

	.site-footer .footer-column h4 {
		color: #ffffff; font-size: 1rem; font-weight: bold; margin-bottom: 10px; padding-bottom: 5px; position: relative;
	}
	/* Horizontal line under heading */

	.site-footer .footer-column h4::after {
		content: ""; display: block; width: 40px; height: 2px; background-color: #ffffff; margin-top: 5px;
	}
	/* Footer body content */

	.footer-column p,
	.footer-column ul {
		margin-bottom: 15px; line-height: 1.5;
	}
	/* Acknowledgement of Country image */

	.acknowledgement-image {
		display: block; margin-top: 12px; max-width: 250px; width: 100%; height: auto;
	}
	/* Bottom site menu */

	.site-footer__menu {
		width: 100%; border-top: 1px solid rgba(255, 255, 255, 0.4); padding-top: 20px; padding-bottom: 10px;
	}
	/* Constrain menu content */

	.site-footer__menu-inner {
		max-width: var(--container-max); margin: 0 auto; text-align: center;
	}

	.site-footer__menu ul {
		list-style: none; padding: 0; margin: 0; display: inline-flex; gap: 20px; flex-wrap: wrap;
	}

	.site-footer__menu a {
		color: #ffffff; font-size: 0.85rem; text-decoration: none;
	}

	.site-footer__menu a:hover {
		text-decoration: underline;
	}
	/* Mobile / Tablet adjustments*/

	@media (max-width: 768px) {
		.site-footer__columns {
			flex-direction: column; gap: 20px; padding: 0 12px;/* add small padding on mobile */
		}
		.footer-column {
			min-width: 100%;
		}
		.site-footer__menu ul {
			flex-direction: column; gap: 10px;
		}
	}
	/* Social links list */

	.social-links {
		list-style: none; padding: 0; margin: 0; display: grid; gap: 8px;
	}
	/* Each link: icon left, text right */

	.social-links a {
		display: inline-flex; align-items: center; color: #ffffff; text-decoration: none; font-size: 10pt;
	}
	/* Icon sizing */

	.social-icon {
		width: 20px; height: auto; max-height: 20px; flex: 0 0 auto; margin-right: 8px; display: inline-block; object-fit: contain;
	}
	/* Hover & focus */

	.social-links a:hover {
		text-decoration: underline;
	}

	.social-links a:focus-visible {
		outline: 2px solid #ffffff; outline-offset: 2px;
	}

</style>","OrgTermsOfService":null,"UseElectedRepresentatives":false,"DisplayMeetingDateOnly":false,"MediaServicesEnabled":true,"LanguageTypeEnum":0,"DateNotationTypeEnum":0}
